import requests

queries = ["truthfulness", "hallucination", "deception LLM", "sycophancy", "lie detection"]
all_results = {}
for q in queries:
    resp = requests.get(f"https://huggingface.co/api/datasets?search={q}&limit=10&sort=downloads", timeout=30)
    if resp.status_code == 200:
        print(f"\n=== Query: '{q}' ===")
        for ds in resp.json():
            ds_id = ds['id']
            downloads = ds.get('downloads', 'N/A')
            print(f"  {ds_id} - downloads: {downloads}")
            all_results[ds_id] = downloads
    else:
        print(f"Query '{q}' failed: {resp.status_code}")

print("\n\n=== TOP DATASETS BY DOWNLOADS ===")
sorted_ds = sorted(all_results.items(), key=lambda x: x[1] if isinstance(x[1], int) else 0, reverse=True)
for ds_id, dl in sorted_ds[:20]:
    print(f"  {ds_id}: {dl}")
PYEOF

